import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Class: BlockRuntimeIds","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/BlockRuntimeIds.md","filePath":"api/@jsprismarine/prismarine/classes/BlockRuntimeIds.md"}`),a={name:`api/@jsprismarine/prismarine/classes/BlockRuntimeIds.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / BlockRuntimeIds</p><h1 id="class-blockruntimeids" tabindex="-1">Class: BlockRuntimeIds <a class="header-anchor" href="#class-blockruntimeids" aria-label="Permalink to “Class: BlockRuntimeIds”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/prismarine/src/block/state/BlockRuntimeIds.ts#L44" target="_blank" rel="noreferrer">packages/prismarine/src/block/state/BlockRuntimeIds.ts:44</a></p><p>Turns a block state into the number that travels in chunk palettes.</p><p>The id is the FNV-1a hash of the block&#39;s own <code>{name, states}</code> compound, serialised as little endian NBT. That choice is what <code>StartGamePacket</code> announces with <code>block_network_ids_are_hashes</code>, and it is what keeps blocks modular: an id depends on nothing but the block itself, so a plugin can add blocks without renumbering anyone else&#39;s, and the server never needs a copy of the client&#39;s internal palette ordering.</p><p>The alternative the protocol allows - the id being a position in the client&#39;s canonical list - would mean shipping and maintaining that exact ordered list for every client version, and would make every plugin block shift the ids of vanilla ones.</p><h2 id="see" tabindex="-1">See <a class="header-anchor" href="#see" aria-label="Permalink to “See”">​</a></h2><p><a href="https://gist.github.com/Alemiz112/504d0f79feac7ef57eda174b668dd345" target="_blank" rel="noreferrer">https://gist.github.com/Alemiz112/504d0f79feac7ef57eda174b668dd345</a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new BlockRuntimeIds</strong>(): <code>BlockRuntimeIds</code></p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>BlockRuntimeIds</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><code>static</code> <strong>get</strong>(<code>state</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/prismarine/src/block/state/BlockRuntimeIds.ts#L172" target="_blank" rel="noreferrer">packages/prismarine/src/block/state/BlockRuntimeIds.ts:172</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="state" tabindex="-1">state <a class="header-anchor" href="#state" aria-label="Permalink to “state”">​</a></h5><p><a href="./BlockState.html"><code>BlockState</code></a></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getbyname" tabindex="-1">getByName() <a class="header-anchor" href="#getbyname" aria-label="Permalink to “getByName()”">​</a></h3><blockquote><p><code>static</code> <strong>getByName</strong>(<code>name</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/prismarine/src/block/state/BlockRuntimeIds.ts#L79" target="_blank" rel="noreferrer">packages/prismarine/src/block/state/BlockRuntimeIds.ts:79</a></p><p>The id of a block in its default state, for the many callers that only know a name. Replaces the old name-keyed mapping, which had no way to say <em>which</em> oak log it meant.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getstate" tabindex="-1">getState() <a class="header-anchor" href="#getstate" aria-label="Permalink to “getState()”">​</a></h3><blockquote><p><code>static</code> <strong>getState</strong>(<code>runtimeId</code>): <a href="./BlockState.html"><code>BlockState</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/prismarine/src/block/state/BlockRuntimeIds.ts#L157" target="_blank" rel="noreferrer">packages/prismarine/src/block/state/BlockRuntimeIds.ts:157</a></p><p>The state an id came from, for reading a chunk back.</p><p>A hash cannot be inverted, so this indexes every state the catalog can produce and looks the id up. Building it costs a pass over ~14k states, so it is deferred until something actually reads a block, and rebuilt when a plugin changes the catalog.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runtimeid" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid" aria-label="Permalink to “runtimeId”">​</a></h5><p><code>number</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./BlockState.html"><code>BlockState</code></a> | <code>null</code></p><hr><h3 id="reset" tabindex="-1">reset() <a class="header-anchor" href="#reset" aria-label="Permalink to “reset()”">​</a></h3><blockquote><p><code>static</code> <strong>reset</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/prismarine/src/block/state/BlockRuntimeIds.ts#L185" target="_blank" rel="noreferrer">packages/prismarine/src/block/state/BlockRuntimeIds.ts:185</a></p><p>Drops memoised ids. Needed after a plugin changes a schema, and by tests.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="serialize" tabindex="-1">serialize() <a class="header-anchor" href="#serialize" aria-label="Permalink to “serialize()”">​</a></h3><blockquote><p><code>static</code> <strong>serialize</strong>(<code>state</code>): <code>Buffer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/prismarine/src/block/state/BlockRuntimeIds.ts#L59" target="_blank" rel="noreferrer">packages/prismarine/src/block/state/BlockRuntimeIds.ts:59</a></p><p>The little endian NBT bytes a state hashes to. Exposed because it is also exactly what <code>StartGamePacket</code> sends for a plugin&#39;s custom blocks.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="state-1" tabindex="-1">state <a class="header-anchor" href="#state-1" aria-label="Permalink to “state”">​</a></h5><p><a href="./BlockState.html"><code>BlockState</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Buffer</code></p><hr><h3 id="trygetbyname" tabindex="-1">tryGetByName() <a class="header-anchor" href="#trygetbyname" aria-label="Permalink to “tryGetByName()”">​</a></h3><blockquote><p><code>static</code> <strong>tryGetByName</strong>(<code>name</code>): <code>number</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/prismarine/src/block/state/BlockRuntimeIds.ts#L108" target="_blank" rel="noreferrer">packages/prismarine/src/block/state/BlockRuntimeIds.ts:108</a></p><p>The same as <a href="#getbyname">getByName</a>, but <code>null</code> rather than a throw for a name that is not a block.</p><p>Items are why this exists. <code>minecraft:stick</code> has no block state and never will, so asking what block it places is an ordinary question with an ordinary answer - not an error, and certainly not one that should cost the packet it was being written into.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name-1" tabindex="-1">name <a class="header-anchor" href="#name-1" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code> | <code>null</code></p><hr><h3 id="trygetbystate" tabindex="-1">tryGetByState() <a class="header-anchor" href="#trygetbystate" aria-label="Permalink to “tryGetByState()”">​</a></h3><blockquote><p><code>static</code> <strong>tryGetByState</strong>(<code>name</code>, <code>states?</code>): <code>number</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/prismarine/src/block/state/BlockRuntimeIds.ts#L128" target="_blank" rel="noreferrer">packages/prismarine/src/block/state/BlockRuntimeIds.ts:128</a></p><p>The id of a block in a particular state, or null if this server has no such block or state.</p><p>The default state is enough for most callers, and <a href="#getbyname">getByName</a> serves them. It is not enough for anything that builds or simulates: a roof is stairs facing four ways, a door is two halves that must agree, and flowing water is the same block at eight different depths. Those are one name with different properties, which a name alone cannot distinguish.</p><p>Memoised, because the callers are world generation and block physics - both of which resolve the same handful of states thousands of times - and building the state object is most of the cost of asking.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name-2" tabindex="-1">name <a class="header-anchor" href="#name-2" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The block&#39;s namespace id.</p><h5 id="states" tabindex="-1">states? <a class="header-anchor" href="#states" aria-label="Permalink to “states?”">​</a></h5><p><code>Readonly</code>&lt;<code>Record</code>&lt;<code>string</code>, <a href="./../type-aliases/BlockStateValue.html"><code>BlockStateValue</code></a>&gt;&gt;</p><p>Properties to set; the rest take defaults.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code> | <code>null</code></p><p>The runtime id, or null rather than a throw: a caller that cannot find a block should lose that detail, not take world generation or the tick down with it.</p>`,88)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};